  "literals": {
    "markov": "El Grafo Predictivo de Markov modela la red sociométrica como un sistema dinámico donde la 'energía social' fluye probabilísticamente. La Masa Gravitacional identifica a los verdaderos 'atractores' del grupo (efecto PageRank).",
    "fourier": "La Transformada Rápida de Fourier (FFT) detecta ciclos ocultos y oscilaciones de poder a través del tiempo en las matrices de ordenación.",
    "termodinamica": "SDR (Densidad Relacional Relativa) y BDR (Densidad Relacional Absoluta) miden el 'estado de agregación' (Sólido, Líquido, Gas, Plasma, Caos) de las interacciones en el grupo.",
    "grassmannian": "Los Puntos Grassmannianos proyectan el ecosistema completo como una 'variedad topológica'. La distancia euclidiana aquí refleja qué tan diferentes son dos matrices en su totalidad estructural."
  }
